insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u0-b1-e1', 'u0-b1', 1, 'TEACH', '{"type":"TEACH","title":"42 letters","body":["The Kazakh Cyrillic alphabet has **42 letters**. 33 are the same as Russian.","**9 letters are special to Kazakh**: Ә І Ң Ғ Ү Ұ Қ Ө Һ.","Ф, в, ц, ч, щ, ъ, ь, э, ё, ю, я appear mostly in borrowed words."],"tip":"Tap any example to hear it."}'::jsonb, 'active', 'high'),
  ('u0-b1-e2', 'u0-b1', 2, 'TEACH', '{"type":"TEACH","title":"Ә and І","body":["**Ә** sounds like the *a* in *apple* or *man*.","**І** is a short *i*, like in *till*."],"examples":[{"kk":"сәлем","en":"hello"},{"kk":"әдемі","en":"beautiful"},{"kk":"дәрігер","en":"doctor"},{"kk":"тіл","en":"language / tongue"},{"kk":"кітап","en":"book"},{"kk":"бір","en":"one"}]}'::jsonb, 'active', 'high'),
  ('u0-b1-e3', 'u0-b1', 3, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"тіл","options":["son","house","snow","language"],"correctAns":"language"}'::jsonb, 'active', 'high'),
  ('u0-b1-e4', 'u0-b1', 4, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"кітап","options":["book","river","doctor","tree"],"correctAns":"book"}'::jsonb, 'active', 'high'),
  ('u0-b1-e5', 'u0-b1', 5, 'LISTENING', '{"type":"LISTENING","audioKk":"әдемі","options":["адемі","әдеми","әдемі"],"correctAns":"әдемі"}'::jsonb, 'active', 'high'),
  ('u0-b1-e6', 'u0-b1', 6, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"дәрігер","options":["doctor","teacher","world","child"],"correctAns":"doctor"}'::jsonb, 'active', 'high'),
  ('u0-b1-e7', 'u0-b1', 7, 'TEACH', '{"type":"TEACH","title":"Ө, Ү and Ұ","body":["**Ө** — like the *ea* in *early*.","**Ү** — say *oo* with your tongue pushed forward (like German *ü*).","**Ұ** — a short *u*, like in *pull*, with the tongue pulled back."],"examples":[{"kk":"өнер","en":"art"},{"kk":"өзен","en":"river"},{"kk":"үй","en":"house"},{"kk":"үш","en":"three"},{"kk":"ұл","en":"son / boy"},{"kk":"ұзын","en":"long"}]}'::jsonb, 'active', 'high'),
  ('u0-b1-e8', 'u0-b1', 8, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["","й"],"options":["ү","ұ","ө"],"correctAns":"ү","hintEn":"house — үй"}'::jsonb, 'active', 'high'),
  ('u0-b1-e9', 'u0-b1', 9, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["","л"],"options":["ө","ү","ұ"],"correctAns":"ұ","hintEn":"son / boy — ұл"}'::jsonb, 'active', 'high'),
  ('u0-b1-e10', 'u0-b1', 10, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["","зен"],"options":["о","ә","ө"],"correctAns":"ө","hintEn":"river — өзен"}'::jsonb, 'active', 'high'),
  ('u0-b1-e11', 'u0-b1', 11, 'LISTENING', '{"type":"LISTENING","audioKk":"үш","options":["іш","үш","ұш"],"correctAns":"үш"}'::jsonb, 'active', 'high'),
  ('u0-b1-e12', 'u0-b1', 12, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"үй","english":"house"},{"kazakh":"ұл","english":"son"},{"kazakh":"өзен","english":"river"},{"kazakh":"бір","english":"one"},{"kazakh":"әдемі","english":"beautiful"}]}'::jsonb, 'active', 'high'),
  ('u0-b1-e13', 'u0-b1', 13, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"өнер","options":["world","art","river","apricot"],"correctAns":"art"}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u0-b2-e1', 'u0-b2', 1, 'TEACH', '{"type":"TEACH","title":"Қ and Ғ","body":["**Қ** is a deep *k* made at the back of the throat.","**Ғ** is a soft, gargled *g* — close to the French *r*."],"examples":[{"kk":"қар","en":"snow"},{"kk":"қыс","en":"winter"},{"kk":"ақша","en":"money"},{"kk":"аға","en":"elder brother"},{"kk":"ағаш","en":"tree"},{"kk":"тоғыз","en":"nine"}]}'::jsonb, 'active', 'high'),
  ('u0-b2-e2', 'u0-b2', 2, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"қар","options":["money","snow","winter","tree"],"correctAns":"snow"}'::jsonb, 'active', 'high'),
  ('u0-b2-e3', 'u0-b2', 3, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"ағаш","options":["snow","river","tree","nine"],"correctAns":"tree"}'::jsonb, 'active', 'high'),
  ('u0-b2-e4', 'u0-b2', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["","ар"],"options":["қ","к","ғ"],"correctAns":"қ","hintEn":"snow — қар"}'::jsonb, 'active', 'high'),
  ('u0-b2-e5', 'u0-b2', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["а","а"],"options":["қ","ғ","г"],"correctAns":"ғ","hintEn":"elder brother — аға"}'::jsonb, 'active', 'high'),
  ('u0-b2-e6', 'u0-b2', 6, 'LISTENING', '{"type":"LISTENING","audioKk":"ақша","options":["аша","ағша","ақша"],"correctAns":"ақша"}'::jsonb, 'active', 'high'),
  ('u0-b2-e7', 'u0-b2', 7, 'TEACH', '{"type":"TEACH","title":"Ң and Һ","body":["**Ң** is the *ng* in *song* — never a separate *n* + *g*.","**Һ** is the English *h*. It''s rare: only a handful of words use it."],"examples":[{"kk":"өлең","en":"song / poem"},{"kk":"он","en":"ten"},{"kk":"оң","en":"right (side)"},{"kk":"айдаһар","en":"dragon"}],"tip":"**он** = ten, but **оң** = right. One letter changes the meaning!"}'::jsonb, 'active', 'high'),
  ('u0-b2-e8', 'u0-b2', 8, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"он","questionEn":"What does this mean?","options":["ten","son","right","snow"],"correctAns":"ten"}'::jsonb, 'active', 'high'),
  ('u0-b2-e9', 'u0-b2', 9, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"оң","questionEn":"What does this mean?","options":["song","nine","right (side)","ten"],"correctAns":"right (side)"}'::jsonb, 'active', 'high'),
  ('u0-b2-e10', 'u0-b2', 10, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"он","english":"ten"},{"kazakh":"оң","english":"right"},{"kazakh":"тоғыз","english":"nine"},{"kazakh":"ақша","english":"money"},{"kazakh":"айдаһар","english":"dragon"}]}'::jsonb, 'active', 'high'),
  ('u0-b2-e11', 'u0-b2', 11, 'LISTENING', '{"type":"LISTENING","audioKk":"өлең","options":["өлен","олең","өлең"],"correctAns":"өлең"}'::jsonb, 'active', 'high'),
  ('u0-b2-e12', 'u0-b2', 12, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"қыс","options":["snow","winter","girl","goose"],"correctAns":"winter"}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u0-b3-e1', 'u0-b3', 1, 'TEACH', '{"type":"TEACH","title":"Review","body":["9 Kazakh letters: **Ә І Ң Ғ Ү Ұ Қ Ө Һ**.","Vowels **ә і ө ү ұ** · consonants **қ ғ ң һ**."],"tip":"**он** = ten, **оң** = right: one letter changes the word."}'::jsonb, 'active', 'high'),
  ('u0-b3-e2', 'u0-b3', 2, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"қар","english":"snow"},{"kazakh":"ағаш","english":"tree"},{"kazakh":"үй","english":"house"},{"kazakh":"тіл","english":"language"},{"kazakh":"өзен","english":"river"}]}'::jsonb, 'active', 'high'),
  ('u0-b3-e3', 'u0-b3', 3, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"бір","english":"one"},{"kazakh":"екі","english":"two"},{"kazakh":"үш","english":"three"},{"kazakh":"тоғыз","english":"nine"},{"kazakh":"он","english":"ten"}]}'::jsonb, 'active', 'high'),
  ('u0-b3-e4', 'u0-b3', 4, 'LISTENING', '{"type":"LISTENING","audioKk":"айдаһар","options":["айдағар","айдар","айдаһар"],"correctAns":"айдаһар"}'::jsonb, 'active', 'high'),
  ('u0-b3-e5', 'u0-b3', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["","ір"],"options":["б","п","м"],"correctAns":"б","hintEn":"one — бір"}'::jsonb, 'active', 'high'),
  ('u0-b3-e6', 'u0-b3', 6, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"екі","options":["one","nine","two","three"],"correctAns":"two"}'::jsonb, 'active', 'high'),
  ('u0-b3-e7', 'u0-b3', 7, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["а","аш"],"options":["ғ","қ","г"],"correctAns":"ғ","hintEn":"tree — ағаш"}'::jsonb, 'active', 'high'),
  ('u0-b3-e8', 'u0-b3', 8, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["өле",""],"options":["ң","г","н"],"correctAns":"ң","hintEn":"song / poem — өлең"}'::jsonb, 'active', 'high'),
  ('u0-b3-e9', 'u0-b3', 9, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","questionEn":"Which letter is special to Kazakh?","options":["Қ","Г","К","Х"],"correctAns":"Қ","scriptOptions":"kk"}'::jsonb, 'active', 'high'),
  ('u0-b3-e10', 'u0-b3', 10, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","questionEn":"Which letter is special to Kazakh?","options":["О","Е","У","Ө"],"correctAns":"Ө","scriptOptions":"kk"}'::jsonb, 'active', 'high'),
  ('u0-b3-e11', 'u0-b3', 11, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"әлем","options":["world","beautiful","art","hello"],"correctAns":"world"}'::jsonb, 'active', 'high'),
  ('u0-b3-e12', 'u0-b3', 12, 'LISTENING', '{"type":"LISTENING","audioKk":"ұзын","options":["озын","үзін","ұзын"],"correctAns":"ұзын"}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u1-b1-e1', 'u1-b1', 1, 'TEACH', '{"type":"TEACH","title":"Hello in Kazakh","body":["Kazakh has two ways to say *you*: **сіз** (polite) and **сен** (friendly). Greetings follow the same split."],"examples":[{"kk":"Сәлеметсіз бе!","en":"Hello! — polite: elders, strangers, work"},{"kk":"Сәлеметсің бе!","en":"Hello! — friendly: friends, family"},{"kk":"Сәлем!","en":"Hi! — casual"}],"tip":"Not sure which one? Use the polite **Сәлеметсіз бе**. It''s never rude."}'::jsonb, 'active', 'high'),
  ('u1-b1-e2', 'u1-b1', 2, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Сәлем!","options":["Bye!","Thank you!","Hi!","Yes!"],"correctAns":"Hi!"}'::jsonb, 'active', 'high'),
  ('u1-b1-e3', 'u1-b1', 3, 'LISTENING', '{"type":"LISTENING","audioKk":"сәлеметсіз бе","options":["сау бол","сәлеметсіз бе","сәлем","сәлеметсің бе"],"correctAns":"сәлеметсіз бе"}'::jsonb, 'active', 'high'),
  ('u1-b1-e4', 'u1-b1', 4, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"Сәлеметсіз бе!","questionEn":"Who would you greet with this?","options":["Your teacher or an older person","Only your little brother","Nobody — it''s rude","Only your cat"],"correctAns":"Your teacher or an older person"}'::jsonb, 'active', 'high'),
  ('u1-b1-e5', 'u1-b1', 5, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"Сәлеметсің бе!","questionEn":"This greeting is…","options":["friendly (to a friend)","polite (to an elder)","a thank-you","a goodbye"],"correctAns":"friendly (to a friend)"}'::jsonb, 'active', 'high'),
  ('u1-b1-e6', 'u1-b1', 6, 'TEACH', '{"type":"TEACH","title":"Good morning, good evening","body":["**Қайырлы** means *good / blessed*. Add a time of day after it:"],"table":{"headers":["Kazakh","Meaning"],"rows":[["таң","morning"],["күн","day / afternoon"],["кеш","evening"],["түн","night"]]},"examples":[{"kk":"Қайырлы таң!","en":"Good morning!"},{"kk":"Қайырлы күн!","en":"Good afternoon!"},{"kk":"Қайырлы кеш!","en":"Good evening!"}],"tip":"**Күн** also means *sun* and *day*."}'::jsonb, 'active', 'high'),
  ('u1-b1-e7', 'u1-b1', 7, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Қайырлы таң!","options":["Good morning!","Good evening!","Thank you!","Good night!"],"correctAns":"Good morning!"}'::jsonb, 'active', 'high'),
  ('u1-b1-e8', 'u1-b1', 8, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Қайырлы кеш!","options":["See you!","Good morning!","Good afternoon!","Good evening!"],"correctAns":"Good evening!"}'::jsonb, 'active', 'high'),
  ('u1-b1-e9', 'u1-b1', 9, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"таң","english":"morning"},{"kazakh":"күн","english":"day"},{"kazakh":"кеш","english":"evening"},{"kazakh":"түн","english":"night"},{"kazakh":"сәлем","english":"hi"}]}'::jsonb, 'active', 'high'),
  ('u1-b1-e10', 'u1-b1', 10, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Қайырлы ","!"],"options":["түн","кеш","таң"],"correctAns":"таң","hintEn":"Good morning!"}'::jsonb, 'active', 'high'),
  ('u1-b1-e11', 'u1-b1', 11, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"Good afternoon!","tiles":["Қайырлы","күн","таң","сәлем"],"correctAns":["Қайырлы","күн"]}'::jsonb, 'active', 'high'),
  ('u1-b1-e12', 'u1-b1', 12, 'LISTENING', '{"type":"LISTENING","audioKk":"қайырлы кеш","options":["қайырлы таң","қайырлы кеш","қайырлы күн"],"correctAns":"қайырлы кеш"}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u1-b2-e1', 'u1-b2', 1, 'TEACH', '{"type":"TEACH","title":"My name is…","body":["**Менің атым …** = *My name is …* (literally: *my name …*).","To ask someone''s name: **Сенің атың кім?** — *What''s your name?* (literally: *your name — who?*)"],"examples":[{"kk":"Менің атым Айгүл.","en":"My name is Aigul."},{"kk":"Сенің атың кім?","en":"What''s your name?"},{"kk":"Менің атым Ержан.","en":"My name is Yerzhan."}],"tip":"There''s no word for *is* here: **атым Айгүл** = *my name [is] Aigul*."}'::jsonb, 'active', 'high'),
  ('u1-b2-e2', 'u1-b2', 2, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Менің атым Айгүл.","options":["My name is Aigul.","Her name is Aigul.","Where is Aigul?","Aigul is happy."],"correctAns":"My name is Aigul."}'::jsonb, 'active', 'high'),
  ('u1-b2-e3', 'u1-b2', 3, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Сенің атың кім?","options":["What''s your name?","Where are you from?","How are you?","Who is she?"],"correctAns":"What''s your name?"}'::jsonb, 'active', 'high'),
  ('u1-b2-e4', 'u1-b2', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Менің "," Айгүл."],"options":["атың","кім","атым"],"correctAns":"атым","hintEn":"My name is Aigul."}'::jsonb, 'active', 'high'),
  ('u1-b2-e5', 'u1-b2', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сенің атың ","?"],"options":["атым","де","кім"],"correctAns":"кім","hintEn":"What''s your name?"}'::jsonb, 'active', 'high'),
  ('u1-b2-e6', 'u1-b2', 6, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"My name is Yerzhan.","tiles":["Менің","атым","Ержан","сенің","кім"],"correctAns":["Менің","атым","Ержан"]}'::jsonb, 'active', 'high'),
  ('u1-b2-e7', 'u1-b2', 7, 'TEACH', '{"type":"TEACH","title":"Nice to meet you","body":["**Қуаныш** = happiness → **қуанышты** = happy.","**Танысқаныма қуаныштымын** = *I''m happy to have met you* — Nice to meet you!","Reply with **Мен де қуаныштымын!** — *Me too!* (**мен де** = me too)"],"examples":[{"kk":"Танысқаныма қуаныштымын.","en":"Nice to meet you."},{"kk":"Мен де қуаныштымын!","en":"Nice to meet you too!"}]}'::jsonb, 'active', 'high'),
  ('u1-b2-e8', 'u1-b2', 8, 'LISTENING', '{"type":"LISTENING","audioKk":"танысқаныма қуаныштымын","options":["менің атым Ержан","мен де қуаныштымын","танысқаныма қуаныштымын"],"correctAns":"танысқаныма қуаныштымын"}'::jsonb, 'active', 'high'),
  ('u1-b2-e9', 'u1-b2', 9, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Мен де қуаныштымын!","options":["I''m tired too!","See you later!","Nice to meet you too!","My name is too!"],"correctAns":"Nice to meet you too!"}'::jsonb, 'active', 'high'),
  ('u1-b2-e10', 'u1-b2', 10, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"Nice to meet you.","tiles":["Танысқаныма","қуаныштымын","мен","де"],"correctAns":["Танысқаныма","қуаныштымын"]}'::jsonb, 'active', 'high'),
  ('u1-b2-e11', 'u1-b2', 11, 'TEACH', '{"type":"TEACH","title":"A shortcut: Сандромын","body":["You can also introduce yourself with just your name plus **-мын / -мін** (*I am*):"],"examples":[{"kk":"Сандро**мын**.","en":"I''m Sandro."},{"kk":"Әсем**мін**.","en":"I''m Assem."},{"kk":"Айдар**мын**.","en":"I''m Aidar."}],"tip":"You''ll learn exactly when it''s **-мын** and when it''s **-мін** in Unit 3."}'::jsonb, 'active', 'high'),
  ('u1-b2-e12', 'u1-b2', 12, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"атым","english":"my name"},{"kazakh":"қуанышты","english":"happy"},{"kazakh":"мен де","english":"me too"},{"kazakh":"кім","english":"who"},{"kazakh":"сенің","english":"your"}]}'::jsonb, 'active', 'high'),
  ('u1-b2-e13', 'u1-b2', 13, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Сандромын.","options":["This is Sandro''s.","I''m Sandro.","Hi, Sandro!","Sandro is here."],"correctAns":"I''m Sandro."}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u1-b3-e1', 'u1-b3', 1, 'TEACH', '{"type":"TEACH","title":"How are you?","body":["**Қалай** = *how*. Add the *you* ending: **Қалайсыз?** (polite) · **Қалайсың?** (friendly).","Answer **Жақсымын** = *I''m good* (**жақсы** good + **-мын** I am). Then ask back: **Сіз ше?** / **Сен ше?** = *And you?*"],"examples":[{"kk":"Қалайсыз?","en":"How are you? (polite)"},{"kk":"Рақмет, жақсымын.","en":"Thanks, I''m good."},{"kk":"Сіз ше?","en":"And you? (polite)"},{"kk":"Мен де жақсымын.","en":"I''m good too."}]}'::jsonb, 'active', 'high'),
  ('u1-b3-e2', 'u1-b3', 2, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Қалайсыз?","options":["How are you? (polite)","What''s your name?","Where are you?","Who are you?"],"correctAns":"How are you? (polite)"}'::jsonb, 'active', 'high'),
  ('u1-b3-e3', 'u1-b3', 3, 'LISTENING', '{"type":"LISTENING","audioKk":"жақсымын","options":["жақсысың","жақсы","жақсымын"],"correctAns":"жақсымын"}'::jsonb, 'active', 'high'),
  ('u1-b3-e4', 'u1-b3', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Рақмет, ","."],"options":["жақсымын","жақсы","жақсысың"],"correctAns":"жақсымын","hintEn":"Thanks, I''m good."}'::jsonb, 'active', 'high'),
  ('u1-b3-e5', 'u1-b3', 5, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Сен ше?","options":["Who are you?","Me too.","Thank you.","And you?"],"correctAns":"And you?"}'::jsonb, 'active', 'high'),
  ('u1-b3-e6', 'u1-b3', 6, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен "," жақсымын."],"options":["де","кім","ше"],"correctAns":"де","hintEn":"I''m good too."}'::jsonb, 'active', 'high'),
  ('u1-b3-e7', 'u1-b3', 7, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"Thanks, I''m good.","tiles":["Рақмет","жақсымын","қалайсың","сен"],"correctAns":["Рақмет","жақсымын"]}'::jsonb, 'active', 'high'),
  ('u1-b3-e8', 'u1-b3', 8, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"And you? (polite)","tiles":["Сіз","ше","Сен","де"],"correctAns":["Сіз","ше"]}'::jsonb, 'active', 'high'),
  ('u1-b3-e9', 'u1-b3', 9, 'TEACH', '{"type":"TEACH","title":"Other ways to ask","body":["**Қалың қалай?** = *How are you doing?* (literally *how is your state?*). Answer: **Қалым жақсы** = *I''m doing well*.","**Аптаң қалай?** = *How''s your week?* · **Күнің қалай?** = *How''s your day?*"],"examples":[{"kk":"Қалың қалай?","en":"How are you doing?"},{"kk":"Қалым жақсы. Сенің ше?","en":"I''m doing well. And yours?"},{"kk":"Аптаң қалай?","en":"How''s your week?"},{"kk":"Күнім жақсы.","en":"My day is good."}]}'::jsonb, 'active', 'high'),
  ('u1-b3-e10', 'u1-b3', 10, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Қалың қалай?","options":["Where is your city?","How are you doing?","What''s your name?","Good evening!"],"correctAns":"How are you doing?"}'::jsonb, 'active', 'high'),
  ('u1-b3-e11', 'u1-b3', 11, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Аптаң қалай?","options":["How''s your week?","Where is your house?","What day is it?","How''s your day?"],"correctAns":"How''s your week?"}'::jsonb, 'active', 'high'),
  ('u1-b3-e12', 'u1-b3', 12, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"қалай","english":"how"},{"kazakh":"жақсы","english":"good"},{"kazakh":"рақмет","english":"thank you"},{"kazakh":"апта","english":"week"},{"kazakh":"күн","english":"day"}]}'::jsonb, 'active', 'high'),
  ('u1-b3-e13', 'u1-b3', 13, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Рақмет, жақсымын. Сіз ","?"],"options":["де","кім","ше"],"correctAns":"ше","hintEn":"Thanks, I''m good. And you?"}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u1-b4-e1', 'u1-b4', 1, 'TEACH', '{"type":"TEACH","title":"Saying goodbye","body":["**Сау бол!** = *Bye!* (literally *be healthy!*) — to a friend.","**Сау болыңыз!** = *Goodbye!* — to someone you call **сіз**.","**Көріскенше!** = *See you!* (literally *until we see each other*)."],"examples":[{"kk":"Сау бол!","en":"Bye! (friendly)"},{"kk":"Сау болыңыз!","en":"Goodbye! (polite)"},{"kk":"Көріскенше!","en":"See you!"}]}'::jsonb, 'active', 'high'),
  ('u1-b4-e2', 'u1-b4', 2, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Сау бол!","options":["Thank you!","Hello!","Bye!","Welcome!"],"correctAns":"Bye!"}'::jsonb, 'active', 'high'),
  ('u1-b4-e3', 'u1-b4', 3, 'LISTENING', '{"type":"LISTENING","audioKk":"сау болыңыз","options":["сау бол","сау болыңыз","сәлеметсіз бе"],"correctAns":"сау болыңыз"}'::jsonb, 'active', 'high'),
  ('u1-b4-e4', 'u1-b4', 4, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Көріскенше!","options":["Welcome!","Good evening!","Nice to meet you!","See you!"],"correctAns":"See you!"}'::jsonb, 'active', 'high'),
  ('u1-b4-e5', 'u1-b4', 5, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"Сау бол!","questionEn":"Who would you say this to?","options":["An elder you just met","Your boss","A friend","A stranger at the bank"],"correctAns":"A friend"}'::jsonb, 'active', 'high'),
  ('u1-b4-e6', 'u1-b4', 6, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сау ","!"],"options":["ше","болыңыз","келдіңіз"],"correctAns":"болыңыз","hintEn":"Goodbye! (polite)"}'::jsonb, 'active', 'high'),
  ('u1-b4-e7', 'u1-b4', 7, 'TEACH', '{"type":"TEACH","title":"Welcome, thanks, yes & no","examples":[{"kk":"Қош келдіңіз!","en":"Welcome!"},{"kk":"Рақмет!","en":"Thank you!"},{"kk":"Иә.","en":"Yes."},{"kk":"Жоқ.","en":"No."}],"tip":"**Жоқ** also means *there isn''t / I don''t have* — you''ll use it a lot in Unit 5."}'::jsonb, 'active', 'high'),
  ('u1-b4-e8', 'u1-b4', 8, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"Қош келдіңіз!","questionEn":"When do you say this?","options":["When leaving","When welcoming a guest","When you say sorry","When you''re hungry"],"correctAns":"When welcoming a guest"}'::jsonb, 'active', 'high'),
  ('u1-b4-e9', 'u1-b4', 9, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"иә","english":"yes"},{"kazakh":"жоқ","english":"no"},{"kazakh":"рақмет","english":"thank you"},{"kazakh":"көріскенше","english":"see you"},{"kazakh":"сау бол","english":"bye"}]}'::jsonb, 'active', 'high'),
  ('u1-b4-e10', 'u1-b4', 10, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"Welcome!","tiles":["Қош","келдіңіз","сау","бол"],"correctAns":["Қош","келдіңіз"]}'::jsonb, 'active', 'high'),
  ('u1-b4-e11', 'u1-b4', 11, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"Bye! (to a friend)","tiles":["Сау","бол","Қош","болыңыз"],"correctAns":["Сау","бол"]}'::jsonb, 'active', 'high'),
  ('u1-b4-e12', 'u1-b4', 12, 'LISTENING', '{"type":"LISTENING","audioKk":"рақмет","options":["көріскенше","рақмет","сәлем"],"correctAns":"рақмет"}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u1-b5-e1', 'u1-b5', 1, 'TEACH', '{"type":"TEACH","title":"Dialogue: meeting someone","examples":[{"kk":"— Қайырлы таң!","en":"Aigul: Good morning!"},{"kk":"— Сәлем!","en":"Yerzhan: Hi!"},{"kk":"— Менің атым Айгүл. Ал сенің атың кім?","en":"Aigul: My name is Aigul. And what''s your name?"},{"kk":"— Менің атым Ержан. Танысқаныма қуаныштымын.","en":"Yerzhan: My name is Yerzhan. Nice to meet you."},{"kk":"— Мен де қуаныштымын!","en":"Aigul: Nice to meet you too!"},{"kk":"— Сау бол!","en":"Yerzhan: Bye!"}],"tip":"**Ал** = *and / so* — it starts a new question: **Ал сенің атың кім?**"}'::jsonb, 'active', 'high'),
  ('u1-b5-e2', 'u1-b5', 2, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Қайырлы таң! — ","!"],"options":["Сау бол","Рақмет","Сәлем"],"correctAns":"Сәлем","hintEn":"Good morning! — Hi!"}'::jsonb, 'active', 'high'),
  ('u1-b5-e3', 'u1-b5', 3, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Менің "," Айгүл. Ал сенің атың кім?"],"options":["атым","қуанышты","атың"],"correctAns":"атым","hintEn":"My name is Aigul. And what''s your name?"}'::jsonb, 'active', 'high'),
  ('u1-b5-e4', 'u1-b5', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Танысқаныма ","."],"options":["қуаныштымын","жақсымын","рақмет"],"correctAns":"қуаныштымын","hintEn":"Nice to meet you."}'::jsonb, 'active', 'high'),
  ('u1-b5-e5', 'u1-b5', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":[""," де қуаныштымын!"],"options":["Сен","Сіз","Мен"],"correctAns":"Мен","hintEn":"Nice to meet you too!"}'::jsonb, 'active', 'high'),
  ('u1-b5-e6', 'u1-b5', 6, 'TEACH', '{"type":"TEACH","title":"Dialogue: a polite hello","examples":[{"kk":"— Сәлеметсіз бе, Олжас!","en":"Arai: Hello, Olzhas!"},{"kk":"— Сәлеметсіз бе, Арай! Қош келдіңіз!","en":"Olzhas: Hello, Arai! Welcome!"},{"kk":"— Рақмет! Қалайсыз?","en":"Arai: Thank you! How are you?"},{"kk":"— Рақмет, жақсымын. Сіз қалайсыз?","en":"Olzhas: Thanks, I''m good. How are you?"},{"kk":"— Мен де жақсымын.","en":"Arai: I''m good too."},{"kk":"— Сау болыңыз!","en":"Olzhas: Goodbye!"},{"kk":"— Көріскенше!","en":"Arai: See you!"}]}'::jsonb, 'active', 'high'),
  ('u1-b5-e7', 'u1-b5', 7, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сәлеметсіз бе, Арай! Қош ","!"],"options":["қалайсыз","келдіңіз","болыңыз"],"correctAns":"келдіңіз","hintEn":"Hello, Arai! Welcome!"}'::jsonb, 'active', 'high'),
  ('u1-b5-e8', 'u1-b5', 8, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Рақмет! ","?"],"options":["Қалайсыз","Көріскенше","Сау болыңыз"],"correctAns":"Қалайсыз","hintEn":"Thank you! How are you?"}'::jsonb, 'active', 'high'),
  ('u1-b5-e9', 'u1-b5', 9, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен де ","."],"options":["жақсымын","қуанышты","рақмет"],"correctAns":"жақсымын","hintEn":"I''m good too."}'::jsonb, 'active', 'high'),
  ('u1-b5-e10', 'u1-b5', 10, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"Hello! How are you? (polite)","tiles":["Сәлеметсіз","бе","қалайсыз","сен","ше"],"correctAns":["Сәлеметсіз","бе","қалайсыз"]}'::jsonb, 'active', 'high'),
  ('u1-b5-e11', 'u1-b5', 11, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"My name is Sandro. What''s your name?","tiles":["Менің","атым","Сандро","Сенің","атың","кім","мен","де"],"correctAns":["Менің","атым","Сандро","Сенің","атың","кім"]}'::jsonb, 'active', 'high'),
  ('u1-b5-e12', 'u1-b5', 12, 'LISTENING', '{"type":"LISTENING","audioKk":"көріскенше","options":["қош келдіңіз","сау болыңыз","көріскенше"],"correctAns":"көріскенше"}'::jsonb, 'active', 'high'),
  ('u1-b5-e13', 'u1-b5', 13, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Қош келдіңіз!","options":["Goodbye!","Good evening!","How are you?","Welcome!"],"correctAns":"Welcome!"}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u2-b3-e1', 'u2-b3', 1, 'TEACH', '{"type":"TEACH","title":"The harmony rule","body":["Kazakh builds words by gluing endings on. Most endings come in a **strong** and a **soft** version, and the word''s vowels decide which one you use."],"table":{"headers":["Group","Vowels"],"rows":[["Soft (“smiley”)","ә ө ү і е"],["Strong","а о ұ ы у"],["Usually strong","я ю и"]]},"tip":"Look at the **last vowel** of the word: бал**а** → strong, ү**й** → soft."}'::jsonb, 'active', 'high'),
  ('u2-b3-e2', 'u2-b3', 2, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"бала","questionEn":"Is the last vowel soft or strong?","options":["Soft","Strong"],"correctAns":"Strong"}'::jsonb, 'active', 'high'),
  ('u2-b3-e3', 'u2-b3', 3, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"үй","questionEn":"Is the last vowel soft or strong?","options":["Strong","Soft"],"correctAns":"Soft"}'::jsonb, 'active', 'high'),
  ('u2-b3-e4', 'u2-b3', 4, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"кітап","questionEn":"Is the last vowel soft or strong?","options":["Strong","Soft"],"correctAns":"Strong"}'::jsonb, 'active', 'high'),
  ('u2-b3-e5', 'u2-b3', 5, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"мектеп","questionEn":"Is the last vowel soft or strong?","options":["Soft","Strong"],"correctAns":"Soft"}'::jsonb, 'active', 'high'),
  ('u2-b3-e6', 'u2-b3', 6, 'TEACH', '{"type":"TEACH","title":"See it in action","body":["The plural ending (*many*) is **-лар** after strong words and **-лер** after soft ones:"],"examples":[{"kk":"бала → бала**лар**","en":"child → children"},{"kk":"қала → қала**лар**","en":"city → cities"},{"kk":"әке → әке**лер**","en":"father → fathers"},{"kk":"бөлме → бөлме**лер**","en":"room → rooms"}]}'::jsonb, 'active', 'high'),
  ('u2-b3-e7', 'u2-b3', 7, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["бала",""],"options":["лар","лер"],"correctAns":"лар","hintEn":"children"}'::jsonb, 'active', 'high'),
  ('u2-b3-e8', 'u2-b3', 8, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["әке",""],"options":["лер","лар"],"correctAns":"лер","hintEn":"fathers"}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u2-b3-2-e1', 'u2-b3-2', 1, 'TEACH', '{"type":"TEACH","title":"The harmony rule","body":["Kazakh builds words by gluing endings on. Most endings come in a **strong** and a **soft** version, and the word''s vowels decide which one you use."],"table":{"headers":["Group","Vowels"],"rows":[["Soft (“smiley”)","ә ө ү і е"],["Strong","а о ұ ы у"],["Usually strong","я ю и"]]},"tip":"Look at the **last vowel** of the word: бал**а** → strong, ү**й** → soft."}'::jsonb, 'active', 'high'),
  ('u2-b3-2-e2', 'u2-b3-2', 2, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"дәрігер","questionEn":"Is the last vowel soft or strong?","options":["Soft","Strong"],"correctAns":"Soft"}'::jsonb, 'active', 'high'),
  ('u2-b3-2-e3', 'u2-b3-2', 3, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"ұшқыш","questionEn":"Is the last vowel soft or strong?","options":["Strong","Soft"],"correctAns":"Strong"}'::jsonb, 'active', 'high'),
  ('u2-b3-2-e4', 'u2-b3-2', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["қала",""],"options":["лер","лар"],"correctAns":"лар","hintEn":"cities"}'::jsonb, 'active', 'high'),
  ('u2-b3-2-e5', 'u2-b3-2', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["бөлме",""],"options":["лар","лер"],"correctAns":"лер","hintEn":"rooms"}'::jsonb, 'active', 'high'),
  ('u2-b3-2-e6', 'u2-b3-2', 6, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","questionEn":"Which vowel is soft?","options":["а","ы","і","ұ"],"correctAns":"і","scriptOptions":"kk"}'::jsonb, 'active', 'high'),
  ('u2-b3-2-e7', 'u2-b3-2', 7, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["тау",""],"options":["лар","лер"],"correctAns":"лар","hintEn":"mountains"}'::jsonb, 'active', 'high'),
  ('u2-b3-2-e8', 'u2-b3-2', 8, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["терезе",""],"options":["лер","лар"],"correctAns":"лер","hintEn":"windows"}'::jsonb, 'active', 'high'),
  ('u2-b3-2-e9', 'u2-b3-2', 9, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"ұл","questionEn":"Is the last vowel soft or strong?","options":["Soft","Strong"],"correctAns":"Strong"}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u2-b4-e1', 'u2-b4', 1, 'TEACH', '{"type":"TEACH","title":"Consonant groups","body":["Endings also look at the **last letter** of the word. Kazakh sorts consonants into three groups:"],"table":{"headers":["Group","Letters"],"rows":[["Voiced","ж з"],["Sonorants","м н ң · л р й у"],["Voiceless","п ф с ш к қ т ч щ ц х һ"]]},"tip":"At the end of a word **б в г д** sound voiceless too: **клуб** sounds like [клуп], **код** like [кот]."}'::jsonb, 'active', 'high'),
  ('u2-b4-e2', 'u2-b4', 2, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"з","questionEn":"Which group is this letter in?","options":["Voiceless","Voiced","Sonorant"],"correctAns":"Voiced"}'::jsonb, 'active', 'high'),
  ('u2-b4-e3', 'u2-b4', 3, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"т","questionEn":"Which group is this letter in?","options":["Voiced","Voiceless","Sonorant"],"correctAns":"Voiceless"}'::jsonb, 'active', 'high'),
  ('u2-b4-e4', 'u2-b4', 4, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"н","questionEn":"Which group is this letter in?","options":["Voiceless","Voiced","Sonorant"],"correctAns":"Sonorant"}'::jsonb, 'active', 'high'),
  ('u2-b4-e5', 'u2-b4', 5, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"қ","questionEn":"Which group is this letter in?","options":["Sonorant","Voiceless","Voiced"],"correctAns":"Voiceless"}'::jsonb, 'active', 'high'),
  ('u2-b4-e6', 'u2-b4', 6, 'TEACH', '{"type":"TEACH","title":"One sound, new word","body":["**з** is voiced, **с** is voiceless. Swap one for the other and you get a different word:"],"examples":[{"kk":"қыз","en":"girl / daughter"},{"kk":"қыс","en":"winter"},{"kk":"қаз","en":"goose"},{"kk":"қас","en":"eyebrow"}]}'::jsonb, 'active', 'high'),
  ('u2-b4-e7', 'u2-b4', 7, 'LISTENING', '{"type":"LISTENING","audioKk":"қыз","options":["қыс","қас","қаз","қыз"],"correctAns":"қыз"}'::jsonb, 'active', 'high'),
  ('u2-b4-e8', 'u2-b4', 8, 'LISTENING', '{"type":"LISTENING","audioKk":"қас","options":["қас","қаз","қыз","қыс"],"correctAns":"қас"}'::jsonb, 'active', 'high'),
  ('u2-b4-e9', 'u2-b4', 9, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"қаз","options":["winter","eyebrow","girl","goose"],"correctAns":"goose"}'::jsonb, 'active', 'high'),
  ('u2-b4-e10', 'u2-b4', 10, 'TEACH', '{"type":"TEACH","title":"Stress: the last syllable","body":["Kazakh stress usually falls on the **last syllable**: бал**а**, қаз**а**қ, алм**а**.","Two exceptions: borrowed words keep their own stress (комп**ью**тер), and personal endings are never stressed: жақс**ы**мын — *I am good*."]}'::jsonb, 'active', 'high'),
  ('u2-b4-e11', 'u2-b4', 11, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"қазақ","questionEn":"Where does the stress usually fall in a Kazakh word?","options":["On the last syllable","On the first syllable","On the middle syllable"],"correctAns":"On the last syllable"}'::jsonb, 'active', 'high'),
  ('u2-b4-e12', 'u2-b4', 12, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"р","questionEn":"Which group is this letter in?","options":["Sonorant","Voiced","Voiceless"],"correctAns":"Sonorant"}'::jsonb, 'active', 'high'),
  ('u2-b4-e13', 'u2-b4', 13, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"ж","questionEn":"Which group is this letter in?","options":["Voiced","Voiceless","Sonorant"],"correctAns":"Voiced"}'::jsonb, 'active', 'high'),
  ('u2-b4-e14', 'u2-b4', 14, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"ш","questionEn":"Which group is this letter in?","options":["Voiced","Voiceless","Sonorant"],"correctAns":"Voiceless"}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u3-b1-e1', 'u3-b1', 1, 'TEACH', '{"type":"TEACH","title":"I, you, he, she…","table":{"headers":["Kazakh","English"],"rows":[["мен","I"],["сен","you (friendly)"],["сіз","you (polite)"],["ол","he / she / it"],["біз","we"],["сендер","you all (friendly)"],["сіздер","you all (polite)"],["олар","they"]]},"tip":"**Ол** means he, she *and* it — Kazakh has no grammatical gender."}'::jsonb, 'active', 'high'),
  ('u3-b1-e2', 'u3-b1', 2, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"мен","english":"I"},{"kazakh":"сен","english":"you (friendly)"},{"kazakh":"ол","english":"he / she / it"},{"kazakh":"біз","english":"we"},{"kazakh":"олар","english":"they"}]}'::jsonb, 'active', 'high'),
  ('u3-b1-e3', 'u3-b1', 3, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"ол","options":["he / she / it","you","they","we"],"correctAns":"he / she / it"}'::jsonb, 'active', 'high'),
  ('u3-b1-e4', 'u3-b1', 4, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"біз","options":["you","they","we","I"],"correctAns":"we"}'::jsonb, 'active', 'high'),
  ('u3-b1-e5', 'u3-b1', 5, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"сіз","questionEn":"Who would you call this?","options":["Your little sister","Your best friend''s dog","Your teacher"],"correctAns":"Your teacher"}'::jsonb, 'active', 'high'),
  ('u3-b1-e6', 'u3-b1', 6, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","promptKk":"сен","questionEn":"This “you” is…","options":["polite / formal","friendly / informal","he or she","plural only"],"correctAns":"friendly / informal"}'::jsonb, 'active', 'high'),
  ('u3-b1-e7', 'u3-b1', 7, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"сіз","english":"you (polite)"},{"kazakh":"сендер","english":"you all (friendly)"},{"kazakh":"сіздер","english":"you all (polite)"},{"kazakh":"мен","english":"I"},{"kazakh":"олар","english":"they"}]}'::jsonb, 'active', 'high'),
  ('u3-b1-e8', 'u3-b1', 8, 'LISTENING', '{"type":"LISTENING","audioKk":"сендер","options":["сендер","сіздер","сен"],"correctAns":"сендер"}'::jsonb, 'active', 'high'),
  ('u3-b1-e9', 'u3-b1', 9, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"олар","options":["they","you all","we","he / she"],"correctAns":"they"}'::jsonb, 'active', 'high'),
  ('u3-b1-e10', 'u3-b1', 10, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":[""," Сандромын."],"options":["Сен","Мен","Ол"],"correctAns":"Мен","hintEn":"I am Sandro."}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u3-b2-e1', 'u3-b2', 1, 'TEACH', '{"type":"TEACH","title":"There''s no word for “am”","body":["To say *I am a doctor*, Kazakh adds an ending to the word itself: **дәрігер** (doctor) → дәрігер**мін** (I am a doctor).","**Мен** (I) is optional: *Мен дәрігермін* = *Дәрігермін*."],"examples":[{"kk":"Мен дәрігер**мін**.","en":"I am a doctor."},{"kk":"Мен Сандро**мын**.","en":"I am Sandro."}]}'::jsonb, 'active', 'high'),
  ('u3-b2-e2', 'u3-b2', 2, 'TEACH', '{"type":"TEACH","title":"-мын or -мін?","body":["After a **vowel** or a **sonorant** (м н ң л р й у) use **-мын / -мін**.","Strong word → **-мын**. Soft word → **-мін**."],"examples":[{"kk":"Бала**мын**.","en":"I am a child."},{"kk":"Адам**мын**.","en":"I am a person."},{"kk":"Жақсы**мын**.","en":"I am good."},{"kk":"Инженер**мін**.","en":"I am an engineer."},{"kk":"Мұғалім**мін**.","en":"I am a teacher."},{"kk":"Әке**мін**.","en":"I am a father."}]}'::jsonb, 'active', 'high'),
  ('u3-b2-e3', 'u3-b2', 3, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен дәрігер","."],"options":["пін","мін","мын"],"correctAns":"мін","hintEn":"I am a doctor."}'::jsonb, 'active', 'high'),
  ('u3-b2-e4', 'u3-b2', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен адам","."],"options":["мын","мін","пын"],"correctAns":"мын","hintEn":"I am a person."}'::jsonb, 'active', 'high'),
  ('u3-b2-e5', 'u3-b2', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен бала","."],"options":["мын","пын","мін"],"correctAns":"мын","hintEn":"I am a child."}'::jsonb, 'active', 'high'),
  ('u3-b2-e6', 'u3-b2', 6, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен мұғалім","."],"options":["мын","пін","мін"],"correctAns":"мін","hintEn":"I am a teacher."}'::jsonb, 'active', 'high'),
  ('u3-b2-e7', 'u3-b2', 7, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен хатшы","."],"options":["мын","мін","пын"],"correctAns":"мын","hintEn":"I am a secretary."}'::jsonb, 'active', 'high'),
  ('u3-b2-e8', 'u3-b2', 8, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен әке","."],"options":["мін","пін","мын"],"correctAns":"мін","hintEn":"I am a father."}'::jsonb, 'active', 'high'),
  ('u3-b2-e9', 'u3-b2', 9, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Мен инженермін.","options":["He is an engineer.","You are an engineer.","I am a teacher.","I am an engineer."],"correctAns":"I am an engineer."}'::jsonb, 'active', 'high'),
  ('u3-b2-e10', 'u3-b2', 10, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Мен оқушымын.","options":["I am a teacher.","I am happy.","She is a student.","I am a student."],"correctAns":"I am a student."}'::jsonb, 'active', 'high'),
  ('u3-b2-e11', 'u3-b2', 11, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"I am a teacher.","tiles":["Мен","мұғаліммін","мұғалім","сен"],"correctAns":["Мен","мұғаліммін"]}'::jsonb, 'active', 'high'),
  ('u3-b2-e12', 'u3-b2', 12, 'LISTENING', '{"type":"LISTENING","audioKk":"дәрігермін","options":["дәрігерсің","дәрігер","дәрігермін"],"correctAns":"дәрігермін"}'::jsonb, 'active', 'high'),
  ('u3-b2-e13', 'u3-b2', 13, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"дәрігер","english":"doctor"},{"kazakh":"мұғалім","english":"teacher"},{"kazakh":"инженер","english":"engineer"},{"kazakh":"оқушы","english":"student"},{"kazakh":"хатшы","english":"secretary"}]}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u3-b3-e1', 'u3-b3', 1, 'TEACH', '{"type":"TEACH","title":"Three families of “I am”","body":["The **last letter** picks м, б or п. The **last vowel** picks ы or і."],"table":{"headers":["Word ends in…","Strong","Soft"],"rows":[["vowel, м н ң л р й у","**-мын** · адам**мын**","**-мін** · дәрігер**мін**"],["ж з","**-бын** · қыз**бын**","**-бін** · тез**бін**"],["voiceless: к қ п с т ш…","**-пын** · қазақ**пын**","**-пін** · әріптес**пін**"]]}}'::jsonb, 'active', 'high'),
  ('u3-b3-e2', 'u3-b3', 2, 'TEACH', '{"type":"TEACH","title":"Examples","examples":[{"kk":"Аспаз**бын**.","en":"I am a chef."},{"kk":"Француз**бын**.","en":"I am French."},{"kk":"Ұшқыш**пын**.","en":"I am a pilot."},{"kk":"Қазақ**пын**.","en":"I am Kazakh."},{"kk":"Олжас**пын**.","en":"I am Olzhas."},{"kk":"Әріптес**пін**.","en":"I am a colleague."}],"tip":"Names work the same way: **Айжанмын**, **Мөлдірмін**, **Қанатпын**."}'::jsonb, 'active', 'high'),
  ('u3-b3-e3', 'u3-b3', 3, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен аспаз","."],"options":["бін","бын","мын"],"correctAns":"бын","hintEn":"I am a chef."}'::jsonb, 'active', 'high'),
  ('u3-b3-e4', 'u3-b3', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен ұшқыш","."],"options":["пін","мын","пын"],"correctAns":"пын","hintEn":"I am a pilot."}'::jsonb, 'active', 'high'),
  ('u3-b3-e5', 'u3-b3', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен қазақ","."],"options":["пін","пын","мын"],"correctAns":"пын","hintEn":"I am Kazakh."}'::jsonb, 'active', 'high'),
  ('u3-b3-e6', 'u3-b3', 6, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен француз","."],"options":["бін","бын","мын"],"correctAns":"бын","hintEn":"I am French."}'::jsonb, 'active', 'high'),
  ('u3-b3-e7', 'u3-b3', 7, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен жұлдыз","."],"options":["мын","бын","бін"],"correctAns":"бын","hintEn":"I am a star."}'::jsonb, 'active', 'high'),
  ('u3-b3-e8', 'u3-b3', 8, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен Мөлдір","."],"options":["пін","мын","мін"],"correctAns":"мін","hintEn":"I am Moldir."}'::jsonb, 'active', 'high')
