insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u3-b5-e1', 'u3-b5', 1, 'TEACH', '{"type":"TEACH","title":"Not = емес","body":["To say *not*, put **емес** after the word, and move the ending onto **емес**.","Емес ends in **с** (voiceless, soft), so it always takes **-пін, -сің, -сіз, -піз, -сіңдер, -сіздер**."],"examples":[{"kk":"Мен мұғаліммін. → Мен мұғалім емес**пін**.","en":"I am a teacher. → I am not a teacher."},{"kk":"Сен инженер емес**сің**.","en":"You are not an engineer."},{"kk":"Ол дәрігер емес.","en":"She is not a doctor."},{"kk":"Біз мұғалім емес**піз**.","en":"We are not teachers."},{"kk":"Бұл телефон емес.","en":"This is not a phone."}]}'::jsonb, 'active', 'high'),
  ('u3-b5-e2', 'u3-b5', 2, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Мен дәрігер емес","."],"options":["пын","пін","мін"],"correctAns":"пін","hintEn":"I am not a doctor."}'::jsonb, 'active', 'high'),
  ('u3-b5-e3', 'u3-b5', 3, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Сіз әже емес","."],"options":["сің","сіз","сыз"],"correctAns":"сіз","hintEn":"You are not a grandma. (polite)"}'::jsonb, 'active', 'high'),
