  ('u4-b1-e4', 'u4-b1', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["әке",""],"options":["дер","лер","лар"],"correctAns":"лер","hintEn":"fathers"}'::jsonb, 'active', 'high'),
  ('u4-b1-e5', 'u4-b1', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["қой",""],"options":["дар","лар","лер"],"correctAns":"лар","hintEn":"sheep (plural)"}'::jsonb, 'active', 'high'),
  ('u4-b1-e6', 'u4-b1', 6, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["терезе",""],"options":["лар","лер","дер"],"correctAns":"лер","hintEn":"windows"}'::jsonb, 'active', 'high'),
  ('u4-b1-e7', 'u4-b1', 7, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["пәтер",""],"options":["дер","лер","лар"],"correctAns":"лер","hintEn":"apartments"}'::jsonb, 'active', 'high'),
  ('u4-b1-e8', 'u4-b1', 8, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["көрші",""],"options":["лар","лер","дер"],"correctAns":"лер","hintEn":"neighbours"}'::jsonb, 'active', 'high'),
