  ('u4-b1-e11', 'u4-b1', 11, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"бала","english":"child"},{"kazakh":"қала","english":"city"},{"kazakh":"бөлме","english":"room"},{"kazakh":"терезе","english":"window"},{"kazakh":"дала","english":"steppe"}]}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u4-b2-e1', 'u4-b2', 1, 'TEACH', '{"type":"TEACH","title":"-дар / -дер","body":["After **л м н ң** or **ж з** → **-дар** (strong) / **-дер** (soft)."],"examples":[{"kk":"адам → адам**дар**","en":"person → people"},{"kk":"қыз → қыз**дар**","en":"girl → girls"},{"kk":"ұл → ұл**дар**","en":"boy → boys"},{"kk":"телефон → телефон**дар**","en":"phone → phones"},{"kk":"үстел → үстел**дер**","en":"table → tables"},{"kk":"гүл → гүл**дер**","en":"flower → flowers"}]}'::jsonb, 'active', 'high'),
