insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u4-b3-e1', 'u4-b3', 1, 'TEACH', '{"type":"TEACH","title":"-тар / -тер","body":["After a **voiceless** consonant (к қ п с т ш…) → **-тар** (strong) / **-тер** (soft)."],"examples":[{"kk":"кітап → кітап**тар**","en":"book → books"},{"kk":"мысық → мысық**тар**","en":"cat → cats"},{"kk":"ит → ит**тер**","en":"dog → dogs"},{"kk":"жүрек → жүрек**тер**","en":"heart → hearts"},{"kk":"мектеп → мектеп**тер**","en":"school → schools"},{"kk":"дос → дос**тар**","en":"friend → friends"}],"tip":"Remember: **б в г д** count as voiceless at the end: клуб → клуб**тар**, велосипед → велосипед**тер**."}'::jsonb, 'active', 'high'),
  ('u4-b3-e2', 'u4-b3', 2, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["әріптес",""],"options":["тар","тер","лер"],"correctAns":"тер","hintEn":"colleagues"}'::jsonb, 'active', 'high'),
  ('u4-b3-e3', 'u4-b3', 3, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["қарындас",""],"options":["тер","лар","тар"],"correctAns":"тар","hintEn":"younger sisters"}'::jsonb, 'active', 'high'),
  ('u4-b3-e4', 'u4-b3', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["құс",""],"options":["тар","тер","лар"],"correctAns":"тар","hintEn":"birds"}'::jsonb, 'active', 'high'),
  ('u4-b3-e5', 'u4-b3', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["ағаш",""],"options":["тер","лар","тар"],"correctAns":"тар","hintEn":"trees"}'::jsonb, 'active', 'high'),
  ('u4-b3-e6', 'u4-b3', 6, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["сұрақ",""],"options":["лар","тер","тар"],"correctAns":"тар","hintEn":"questions"}'::jsonb, 'active', 'high'),
  ('u4-b3-e7', 'u4-b3', 7, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["сурет",""],"options":["тер","лер","тар"],"correctAns":"тер","hintEn":"pictures"}'::jsonb, 'active', 'high'),
  ('u4-b3-e8', 'u4-b3', 8, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["туыс",""],"options":["тар","тер","лар"],"correctAns":"тар","hintEn":"relatives"}'::jsonb, 'active', 'high'),
