  ('u4-b3-e10', 'u4-b3', 10, 'LISTENING', '{"type":"LISTENING","audioKk":"кітаптар","options":["кітаптар","кітап","кітапдар"],"correctAns":"кітаптар"}'::jsonb, 'active', 'high'),
