insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u5-b2-e1', 'u5-b2', 1, 'TEACH', '{"type":"TEACH","title":"My = менің + an ending","body":["**Менің** means *my*, and the noun also takes an ending. You can drop менің — the ending alone is enough."],"table":{"headers":["Word ends in…","Strong","Soft"],"rows":[["a vowel","**-м** · бала**м**","**-м** · әке**м**"],["a consonant","**-ым** · ат**ым**","**-ім** · үй**ім**"]]},"examples":[{"kk":"менің үй**ім**","en":"my house"},{"kk":"менің ат**ым**","en":"my name"},{"kk":"бала**м**","en":"my child"},{"kk":"әйел**ім**","en":"my wife"}]}'::jsonb, 'active', 'high'),
