  ('u5-b2-e4', 'u5-b2', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Менің ","."],"options":["қызм","қызым","қызім"],"correctAns":"қызым","hintEn":"my daughter"}'::jsonb, 'active', 'high'),
