  ('u5-b3-e1', 'u5-b3', 1, 'TEACH', '{"type":"TEACH","title":"Whose? Endings for everyone","table":{"headers":["Whose?","After a vowel","After a consonant"],"rows":[["менің — my","бала**м**","үй**ім**"],["сенің — your","бала**ң**","үй**ің**"],["сіздің — your (polite)","бала**ңыз**","үй**іңіз**"],["оның — his / her","бала**сы**","үй**і**"],["біздің — our","бала**мыз**","үй**іміз**"]]},"tip":"*Their* = **олардың** + the same ending as оның: олардың үй**і**."}'::jsonb, 'active', 'high'),
