  ('u6-b5-e5', 'u6-b5', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["дүйсенбі",""],"options":["те","да","де"],"correctAns":"де","hintEn":"on Monday"}'::jsonb, 'active', 'high'),
  ('u6-b5-e6', 'u6-b5', 6, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["жұма",""],"options":["да","де","та"],"correctAns":"да","hintEn":"on Friday"}'::jsonb, 'active', 'high'),
