  ('u7-b4-e4', 'u7-b4', 4, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"шай","english":"tea"},{"kazakh":"су","english":"water"},{"kazakh":"сүт","english":"milk"},{"kazakh":"тамақ","english":"food"},{"kazakh":"қара","english":"black"}]}'::jsonb, 'active', 'high'),
  ('u7-b4-e5', 'u7-b4', 5, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Досым күнде қара шай ішеді.","options":["My friend drinks black coffee today.","My friend drinks green tea every day.","I drink black tea every day.","My friend drinks black tea every day."],"correctAns":"My friend drinks black tea every day."}'::jsonb, 'active', 'high'),
  ('u7-b4-e6', 'u7-b4', 6, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"I usually drink black coffee.","tiles":["Әдетте","қара","кофе","ішемін","ішеді","ақ"],"correctAns":["Әдетте","қара","кофе","ішемін"]}'::jsonb, 'active', 'high'),
  ('u7-b4-e7', 'u7-b4', 7, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Көп жұмыс істеймін.","options":["I don''t work much.","She works a lot.","I have a lot of work.","I work a lot."],"correctAns":"I work a lot."}'::jsonb, 'active', 'high'),
  ('u7-b4-e8', 'u7-b4', 8, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Көп ұйықтаймын.","options":["I sleep early.","I eat a lot.","I don''t sleep.","I sleep a lot."],"correctAns":"I sleep a lot."}'::jsonb, 'active', 'high'),
  ('u7-b4-e9', 'u7-b4', 9, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"My daughter wakes up early.","tiles":["Қызым","ерте","оянады","ертең","оянамын"],"correctAns":["Қызым","ерте","оянады"]}'::jsonb, 'active', 'high'),
  ('u7-b4-e10', 'u7-b4', 10, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Досым "," кофе ішеді."],"options":["сүтте","сүтпен","сүт"],"correctAns":"сүтпен","hintEn":"My friend drinks coffee with milk."}'::jsonb, 'active', 'high'),
  ('u7-b4-e11', 'u7-b4', 11, 'LISTENING', '{"type":"LISTENING","audioKk":"әдетте","options":["ертең","күнде","әдетте"],"correctAns":"әдетте"}'::jsonb, 'active', 'high'),
  ('u7-b4-e12', 'u7-b4', 12, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Сенбіде онда пицца пісіремін.","options":["On Sunday at 10 I cook pizza.","On Saturday I eat pizza.","On Saturday at 10 I cook pizza.","On Saturday at 10 I order pizza."],"correctAns":"On Saturday at 10 I cook pizza."}'::jsonb, 'active', 'high'),
  ('u7-b4-e13', 'u7-b4', 13, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Жақсы досым әдетте әдемі кафеде қара шай ішеді.","options":["My good friend drinks black tea at home.","My good friend usually drinks black tea in a beautiful café.","I usually drink black tea in a beautiful café.","My good friend usually drinks green tea in a beautiful café."],"correctAns":"My good friend usually drinks black tea in a beautiful café."}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u7-b5-e1', 'u7-b5', 1, 'TEACH', '{"type":"TEACH","title":"Don''t: -ма, -ба, -па","body":["Put the negative between the **stem** and the ending, then add **й**:"],"table":{"headers":["Stem ends in…","Negative","Example"],"rows":[["vowel, л р й у","**-ма / -ме**","бар**ма**ймын — I don''t go"],["ж з м н ң","**-ба / -бе**","жаз**ба**ймын — I don''t write"],["voiceless: п с т ш к қ…","**-па / -пе**","іш**пе**ймін — I don''t drink"]]},"examples":[{"kk":"Ертең жұмыс істе**ме**ймін, демаламын.","en":"Tomorrow I don''t work, I rest."},{"kk":"Кітап жаз**ба**ймын, имейл жазамын.","en":"I don''t write a book, I write an email."},{"kk":"Әкем Қазақстанда тұр**ма**йды.","en":"My dad doesn''t live in Kazakhstan."}]}'::jsonb, 'active', 'high'),
  ('u7-b5-e2', 'u7-b5', 2, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Ертең тамақ ","."],"options":["пісірбеймін","пісірмеймін","пісірпеймін"],"correctAns":"пісірмеймін","hintEn":"Tomorrow I won''t cook."}'::jsonb, 'active', 'high'),
  ('u7-b5-e3', 'u7-b5', 3, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Испанияда ","."],"options":["тұрпаймын","тұрмаймын","тұрбаймын"],"correctAns":"тұрмаймын","hintEn":"I don''t live in Spain."}'::jsonb, 'active', 'high'),
  ('u7-b5-e4', 'u7-b5', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Кешке кофе ","."],"options":["ішбеймін","ішмеймін","ішпеймін"],"correctAns":"ішпеймін","hintEn":"I don''t drink coffee in the evening."}'::jsonb, 'active', 'high'),
  ('u7-b5-e5', 'u7-b5', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Кеш ","."],"options":["оянпаймын","оянбаймын","оянмаймын"],"correctAns":"оянбаймын","hintEn":"I don''t wake up late."}'::jsonb, 'active', 'high'),
  ('u7-b5-e6', 'u7-b5', 6, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Ертең қызым эссе ","."],"options":["жазпайды","жазмайды","жазбайды"],"correctAns":"жазбайды","hintEn":"Tomorrow my daughter won''t write an essay."}'::jsonb, 'active', 'high'),
  ('u7-b5-e7', 'u7-b5', 7, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Қарындасым Сингапурда ","."],"options":["тұрбайды","тұрмайды","тұрпайды"],"correctAns":"тұрмайды","hintEn":"My younger sister doesn''t live in Singapore."}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u7-b5-2-e1', 'u7-b5-2', 1, 'TEACH', '{"type":"TEACH","title":"Questions: ма / ме, ба / бе","body":["To ask a yes/no question, put a particle **after** the verb.","After **-ды/-ді** and **-сыңдар, -сыздар** → **ма / ме**. After **-мын, -сың, -сыз, -мыз** → **ба / бе**."],"examples":[{"kk":"Барасың **ба**?","en":"Are you going?"},{"kk":"Кофе ішесің **бе**?","en":"Do you drink coffee?"},{"kk":"Ол жұмыс істейді **ме**?","en":"Does she work?"},{"kk":"Ертең сабақтарың бар **ма**?","en":"Do you have lessons tomorrow?"}]}'::jsonb, 'active', 'high'),
  ('u7-b5-2-e2', 'u7-b5-2', 2, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Кофе ішесің ","?"],"options":["ба","бе","ме"],"correctAns":"бе","hintEn":"Do you drink coffee?"}'::jsonb, 'active', 'high'),
  ('u7-b5-2-e3', 'u7-b5-2', 3, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Ол жұмыс істейді ","?"],"options":["ме","бе","ма"],"correctAns":"ме","hintEn":"Does she work?"}'::jsonb, 'active', 'high'),
  ('u7-b5-2-e4', 'u7-b5-2', 4, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Барасыз ","?"],"options":["ба","ма","бе"],"correctAns":"ба","hintEn":"Are you going? (polite)"}'::jsonb, 'active', 'high'),
  ('u7-b5-2-e5', 'u7-b5-2', 5, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Ертең сабақтарың бар ма?","options":["Do you have lessons tomorrow?","Where are your lessons tomorrow?","You have lessons tomorrow.","Do you have lessons today?"],"correctAns":"Do you have lessons tomorrow?"}'::jsonb, 'active', 'high'),
  ('u7-b5-2-e6', 'u7-b5-2', 6, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"I don''t work tomorrow, I rest.","tiles":["Ертең","жұмыс","істемеймін","демаламын","істеймін","демалмаймын"],"correctAns":["Ертең","жұмыс","істемеймін","демаламын"]}'::jsonb, 'active', 'high'),
  ('u7-b5-2-e7', 'u7-b5-2', 7, 'LISTENING', '{"type":"LISTENING","audioKk":"бармаймын","options":["бармайды","барамын","бармаймын"],"correctAns":"бармаймын"}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u7-b6-e1', 'u7-b6', 1, 'TEACH', '{"type":"TEACH","title":"I like: маған … ұнайды","body":["Kazakh says *to me … is pleasing*: **маған** (to me) + the thing + **ұнайды**.","To like *doing* something, use the verb in its **-у** form: маған ерте ояну ұнайды = I like waking up early."],"table":{"headers":["","Kazakh","English"],"rows":[["+","маған кофе **ұнайды**","I like coffee"],["−","маған кофе **ұнамайды**","I don''t like coffee"],["?","саған кофе **ұнай ма**?","Do you like coffee?"]]},"examples":[{"kk":"Маған жұмыс істеу ұнайды.","en":"I like working."},{"kk":"Саған Сингапурда тұру ұнай ма?","en":"Do you like living in Singapore?"},{"kk":"Иә, маған Қазақстанда тұру ұнайды.","en":"Yes, I like living in Kazakhstan."}]}'::jsonb, 'active', 'high'),
  ('u7-b6-e2', 'u7-b6', 2, 'TEACH', '{"type":"TEACH","title":"To me, to you …","table":{"headers":["Pronoun","to …","","Pronoun","to …"],"rows":[["мен","**маған**","","біз","**бізге**"],["сен","**саған**","","сендер","**сендерге**"],["сіз","**сізге**","","сіздер","**сіздерге**"],["ол","**оған**","","олар","**оларға**"]]},"tip":"Only the pronoun changes: **ұнайды** stays the same for everyone. Сізге кофе ұнай ма? = Do you (polite) like coffee?"}'::jsonb, 'active', 'high'),
  ('u7-b6-e3', 'u7-b6', 3, 'MATCH_PAIRS', '{"type":"MATCH_PAIRS","pairs":[{"kazakh":"маған","english":"to me"},{"kazakh":"саған","english":"to you"},{"kazakh":"сізге","english":"to you (polite)"},{"kazakh":"оған","english":"to him / her"},{"kazakh":"бізге","english":"to us"}]}'::jsonb, 'active', 'high'),
  ('u7-b6-e4', 'u7-b6', 4, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","questionEn":"How do you say ''to them''?","options":["оларға","оларда","олар"],"correctAns":"оларға","scriptOptions":"kk"}'::jsonb, 'active', 'high'),
  ('u7-b6-e5', 'u7-b6', 5, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Маған кофе ұнайды.","options":["I need coffee.","I like coffee.","I don''t like coffee.","You like coffee."],"correctAns":"I like coffee."}'::jsonb, 'active', 'high'),
  ('u7-b6-e6', 'u7-b6', 6, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Саған нан жеу ұнай ма?","options":["I like eating bread.","Do you like eating bread?","Do you need bread?","Do you like baking bread?"],"correctAns":"Do you like eating bread?"}'::jsonb, 'active', 'high'),
  ('u7-b6-e7', 'u7-b6', 7, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Маған кеш ояну ","."],"options":["ұнайды","ұнамайды","ұнай ма"],"correctAns":"ұнайды","hintEn":"I like waking up late."}'::jsonb, 'active', 'high'),
  ('u7-b6-e8', 'u7-b6', 8, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":[""," ерте ояну ұнай ма?"],"options":["Сізге","Сіз","Сізде"],"correctAns":"Сізге","hintEn":"Do you like waking up early? (polite)"}'::jsonb, 'active', 'high'),
  ('u7-b6-e9', 'u7-b6', 9, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"I like working.","tiles":["Маған","жұмыс","істеу","ұнайды","Мен","ұнамайды"],"correctAns":["Маған","жұмыс","істеу","ұнайды"]}'::jsonb, 'active', 'high'),
  ('u7-b6-e10', 'u7-b6', 10, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"I don''t like living in Germany.","tiles":["Маған","Германияда","тұру","ұнамайды","ұнайды","Германия"],"correctAns":["Маған","Германияда","тұру","ұнамайды"]}'::jsonb, 'active', 'high')
insert into public.exercises (id, lesson_id, "order", type, prompt, status, confidence) values
  ('u7-b6-2-e1', 'u7-b6-2', 1, 'TEACH', '{"type":"TEACH","title":"I need: маған … керек","body":["Same pattern: **маған** + the thing + **керек** (necessary). For *don''t need*, add **жоқ**: керек **жоқ**. For a question, add **пе**: керек **пе**?"],"examples":[{"kk":"Маған ақ нан керек.","en":"I need white bread."},{"kk":"Маған кофе керек **жоқ**.","en":"I don''t need coffee."},{"kk":"Саған кофе керек пе?","en":"Do you need coffee?"},{"kk":"Маған ерте ояну керек.","en":"I need to wake up early."},{"kk":"Маған су **да** керек.","en":"I also need water."}],"tip":"**да / де / та / те** after a word means *too*: су **да** (water too), досым **да** (my friend too), мысық **та** (a cat too). It follows the same rule as -да/-та, but it''s written as a separate word."}'::jsonb, 'active', 'high'),
  ('u7-b6-2-e2', 'u7-b6-2', 2, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Маған қара кофе керек.","options":["I like black coffee.","You need black coffee.","I need black coffee.","I need black tea."],"correctAns":"I need black coffee."}'::jsonb, 'active', 'high'),
  ('u7-b6-2-e3', 'u7-b6-2', 3, 'TRANSLATE_EN_KK', '{"type":"TRANSLATE_EN_KK","promptEn":"I need white bread.","tiles":["Маған","ақ","нан","керек","қара","ұнайды"],"correctAns":["Маған","ақ","нан","керек"]}'::jsonb, 'active', 'high'),
  ('u7-b6-2-e4', 'u7-b6-2', 4, 'TRANSLATE_KK_EN', '{"type":"TRANSLATE_KK_EN","promptKk":"Саған ерте ояну керек пе?","options":["Do you like waking up early?","Do you need to wake up early?","Do you wake up early?","I need to wake up early."],"correctAns":"Do you need to wake up early?"}'::jsonb, 'active', 'high'),
  ('u7-b6-2-e5', 'u7-b6-2', 5, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Маған су "," керек."],"options":["да","де","та"],"correctAns":"да","hintEn":"I also need water."}'::jsonb, 'active', 'high'),
  ('u7-b6-2-e6', 'u7-b6-2', 6, 'FILL_BLANK', '{"type":"FILL_BLANK","sentenceKkParts":["Қызым "," жақсы."],"options":["де","да","та"],"correctAns":"да","hintEn":"My daughter is also good."}'::jsonb, 'active', 'high')
