  ('u7-b6-3-e2', 'u7-b6-3', 2, 'MULTIPLE_CHOICE', '{"type":"MULTIPLE_CHOICE","questionEn":"What does мүмкін mean?","options":["yes","maybe","never","no"],"correctAns":"maybe"}'::jsonb, 'active', 'high'),
